mapper.select:
SELECT SERIALNO, FUNDACCT, TRADEACCO, BANKNO, NETPOINT, BANKACCO, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, INVTP, INVNM, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, APKIND, FUNDID, SUBAMT, CURRENCYTYPE, SUBQUTY, COMMRO, OSEATNO, (SELECT SEATNM FROM SEAT WHERE SEATNO = OSEATNO) OSEATNM, V.OFUNDID, (SELECT FUNDNM FROM FUNDINFO WHERE FUNDID = V.OFUNDID) OFUNDNAME, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, MELONMD, DIVIDENDRATE, LARGEREDEEMFLAG, OLDAPPNO, WORKDATE, APDT, APTM, APPLYST, REGIONCODE, BROKER, BKIDTP, FUNDNM, BKIDNO, CCHKFLAG, OFUNDACCT, OTRADEACCO, FROZENCAUSE, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, BROKERTEL, BROKERFAX, APPNO FROM V_APPTRADETODAY V WHERE 1 = 1
AND WORKDATE = #{sp.appDate}
AND APKIND = #{sp.selApkindOne}
AND TRIM(FUNDACCT) = #{sp.fundacct}
AND INVNM LIKE '%'||#{sp.invnm}||'%'
AND TANO = #{sp.tano}
AND FUNDID = #{sp.fundcode}
AND FUNDNM LIKE '%'||#{sp.fundname}||'%'
AND REGIONCODE = #{sp.qway}
AND NETPOINT = #{sp.netpoint}
ORDER BY INVNM,CONCAT(APDT,APTM),APPNO ASC

SELECT SERIALNO, FUNDACCT, TRADEACCO, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, INVTP, INVNM, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, APKIND, FUNDID, FUNDNM, SUBAMT, CURRENCYTYPE, SUBQUTY, COMMRO, OSEATNO, (SELECT SEATNM FROM SEAT WHERE SEATNO = OSEATNO) OSEATNM, V.OFUNDID, (SELECT FUNDNM FROM FUNDINFO WHERE FUNDID = V.OFUNDID) OFUNDNAME, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, MELONMD, DIVIDENDRATE, LARGEREDEEMFLAG, OLDAPPNO, WORKDATE, APDT, APTM, REGIONCODE, BROKER, BKIDTP, BKIDNO, CCHKFLAG, OFUNDACCT, OTRADEACCO, FROZENCAUSE, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, BROKERTEL, BROKERFAX, APPNO FROM V_APPTRADETODAY V WHERE 1 = 1
AND WORKDATE = #{sp.appDate}
AND APKIND = #{sp.selApkindOne}
AND TRIM(FUNDACCT) = #{sp.fundacct}
AND IDNO = #{sp.idno}
AND INVNM LIKE '%'||#{sp.invnm}||'%'
AND TANO = #{sp.tano}
AND FUNDID = #{sp.fundcode}
AND FUNDNM LIKE '%'||#{sp.fundname}||'%'
AND REGIONCODE = #{sp.qway}
AND NETPOINT = #{sp.netpoint}
ORDER BY INVNM,CONCAT(APDT,APTM),APPNO ASC

	 SELECT 
		  	 COUNT(*)            
	    FROM V_APPTRADETODAY
	   WHERE 1 = 1

  		 AND WORKDATE = #{sp.appDate}


  		 AND APKIND = #{sp.selApkindOne}


  		 AND TRIM(FUNDACCT) = #{sp.fundacct}


  		 AND IDNO = #{sp.idno}


  		 AND INVNM LIKE '%'||#{sp.invnm}||'%' 


  		 AND TANO = #{sp.tano}


  		 AND FUNDID = #{sp.fundcode}


  		 AND FUNDNM LIKE '%'||#{sp.fundname}||'%'


  		 AND REGIONCODE = #{sp.qway}


  		 AND NETPOINT = #{sp.netpoint}

	ORDER BY INVNM,CONCAT(APDT,APTM),APPNO ASC

SELECT * FROM ( SELECT B.TRANSFERDT, (SELECT NETPOINT FROM TRADEACCOINFO WHERE TRADEACCO = B.TRADEACCO) NETPOINT, B.CAPITALNO, F.FUNDACCT, C.INVNM, B.TRADEACCO, B.BANKNO, B.BANKACCO, B.CAPITALTP, B.SERIALNO, B.APDT, IBF_GET_PARAMNAME('SYSTEM','APKIND',B.APKIND) APKIND_NAME, B.APKIND, B.FUNDID, B.CURRENCYTYPE, B.SUBAMT, B.ACKAMT, B.DEBIT, B.DCFLAG, B.CHKFLAG, T1.EMNAME AS TELLER, T2.EMNAME AS CHECKER, B.PAYMENTNO, B.PAYMENTFLAG, B.PAYMENTMSG , F.TANO FROM (SELECT CC.TRANSFERDT, CC.CAPITALNO, CC.TRADEACCO, CC.BANKNO, CC.BANKACCO, CC.CAPITALTP, CC.CUSTNO, CC.SERIALNO, CC.APDT, CC.APKIND, CC.FUNDID, CC.CURRENCYTYPE, CC.SUBAMT, CC.ACKAMT, CC.DEBIT, CC.DCFLAG, SS.CHKFLAG, SS.TELLER, SS.CHECKER, SS.PAYMENTFLAG, SS.PAYMENTNO, SS.PAYMENTMSG FROM CAPITALBLOTTER CC, CAPITALSTATUS SS WHERE CC.CAPITALNO = SS.REFERNO AND SS.SEQNO = (SELECT MAX(SEQNO) FROM CAPITALSTATUS WHERE REFERNO = CC.CAPITALNO)
AND CC.TRANSFERDT >= #{sp.startDate}
AND CC.TRANSFERDT <= #{sp.endDate}
AND CC.APKIND = #{sp.selApkindOne}
) B, CUSTINFO C, (SELECT RR.TRADEACCO, FF.FUNDID, RR.FUNDACCT, RR.TANO FROM FUNDINFO FF, TRADEACCORELA RR WHERE FF.TANO = RR.TANO) F, FUNDINFO I,
T_ECC_EMPLOYEE T1, T_ECC_EMPLOYEE T2 WHERE B.CUSTNO = C.CUSTNO AND B.FUNDID = I.FUNDID AND B.TRADEACCO = F.TRADEACCO(+) AND B.FUNDID = F.FUNDID(+) AND B.TELLER = T1.EMPID(+) AND B.CHECKER = T2.EMPID(+) ) WHERE 1 = 1
AND FUNDACCT = #{sp.fundacct}
AND INVNM LIKE '%' || #{sp.invnm} || '%'
AND TANO = #{sp.tano}
AND NETPOINT = #{sp.netpoint}
ORDER BY INVNM,APDT,CAPITALNO ASC

SELECT COUNT(*) FROM ( SELECT B.TRANSFERDT, (SELECT NETPOINT FROM TRADEACCOINFO WHERE TRADEACCO = B.TRADEACCO) NETPOINT, B.CAPITALNO, F.FUNDACCT, C.INVNM, B.TRADEACCO, B.BANKNO, B.BANKACCO, B.CAPITALTP, B.SERIALNO, B.APDT, IBF_GET_PARAMNAME('SYSTEM','APKIND',B.APKIND) APKIND_NAME, B.APKIND, B.FUNDID, B.CURRENCYTYPE, B.SUBAMT, B.ACKAMT, B.DEBIT, B.DCFLAG, B.CHKFLAG, T1.EMNAME AS TELLER, T2.EMNAME AS CHECKER, B.PAYMENTNO, B.PAYMENTFLAG, B.PAYMENTMSG , F.TANO FROM (SELECT CC.TRANSFERDT, CC.CAPITALNO, CC.TRADEACCO, CC.BANKNO, CC.BANKACCO, CC.CAPITALTP, CC.CUSTNO, CC.SERIALNO, CC.APDT, CC.APKIND, CC.FUNDID, CC.CURRENCYTYPE, CC.SUBAMT, CC.ACKAMT, CC.DEBIT, CC.DCFLAG, SS.CHKFLAG, SS.TELLER, SS.CHECKER, SS.PAYMENTFLAG, SS.PAYMENTNO, SS.PAYMENTMSG FROM CAPITALBLOTTER CC, CAPITALSTATUS SS WHERE CC.CAPITALNO = SS.REFERNO AND SS.SEQNO = (SELECT MAX(SEQNO) FROM CAPITALSTATUS WHERE REFERNO = CC.CAPITALNO)
AND CC.TRANSFERDT >= #{sp.startDate}
AND CC.TRANSFERDT <= #{sp.endDate}
AND CC.APKIND = #{sp.selApkindOne}
) B, CUSTINFO C, (SELECT RR.TRADEACCO, FF.FUNDID, RR.FUNDACCT, RR.TANO FROM FUNDINFO FF, TRADEACCORELA RR WHERE FF.TANO = RR.TANO) F, FUNDINFO I,
T_ECC_EMPLOYEE T1, T_ECC_EMPLOYEE T2 WHERE B.CUSTNO = C.CUSTNO AND B.FUNDID = I.FUNDID AND B.TRADEACCO = F.TRADEACCO(+) AND B.FUNDID = F.FUNDID(+) AND B.TELLER = T1.EMPID(+) AND B.CHECKER = T2.EMPID(+)) WHERE 1 = 1
AND FUNDACCT = #{sp.fundacct}
AND INVNM LIKE '%' || #{sp.invnm} || '%'
AND TANO = #{sp.tano}
AND NETPOINT = #{sp.netpoint}
ORDER BY INVNM,APDT,CAPITALNO ASC

SELECT A.ACKDT, A.ACKNO, A.RETCODE, A.RETMSG, A.APDT, A.SERIALNO, A.APPNO, A.FUNDACCT, A.TRADEACCO, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, A.FUNDID, IBF_GET_PARAMNAME('SYSTEM','APKIND',A.APKIND) APKIND_NAME, A.APKIND, A.CURRENCYTYPE, A.SUBQUTY, A.SUBAMT, A.ACKQUTY, A.ACKAMT, A.BALANCE, A.COMMRO, A.SHARETYPE, A.FEE, A.INTEREST, A.ACKNAV, A.OSEATNO, (SELECT SEATNM FROM SEAT WHERE SEATNO = A.OSEATNO) OSEATNM, A.OFUNDID, A.OFUNDACCT, A.OTRADEACCO, A.OLDAPPNO, A.NETPOINT, IBF_GET_PARAMNAME('SYSTEM','MELONMD',A.MELONMD) MELONMD_NAME, A.MELONMD, A.DIVIDENDRATE, A.FROZENCAUSE, A.APPLYST FROM S_ACKTRADEBLOTTER A, CUSTINFO C WHERE A.CUSTNO = C.CUSTNO
AND A.FUNDACCT = #{sp.fundacct}
AND C.INVNM LIKE '%' || #{sp.invnm} || '%'
AND A.APKIND = #{sp.selApkindTwo}
AND A.TANO = #{sp.tano}
AND A.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,A.ACKDT,A.APPNO ASC

		SELECT 
			 COUNT(*)
	    FROM S_ACKTRADEBLOTTER A,
	         CUSTINFO C
	   WHERE A.CUSTNO = C.CUSTNO

  		 	AND A.FUNDACCT = #{sp.fundacct}


	  		 AND C.INVNM LIKE '%' || #{sp.invnm} || '%'


	  		 AND A.APKIND = #{sp.selApkindTwo}


	  		 AND A.TANO = #{sp.tano}


	  		 AND A.NETPOINT = #{sp.netpoint}

	    ORDER BY C.INVNM,A.ACKDT,A.APPNO ASC

SELECT ACKDT, ACKNO, RETCODE, RETMSG, APDT, SERIALNO, APPNO, FUNDID, IBF_GET_PARAMNAME('SYSTEM','APKIND',APKIND) APKIND_NAME, APKIND, FUNDACCT, TRADEACCO, BANKNO, BANKACCO, INVNM, IBF_GET_PARAMNAME('SYSTEM','INVTP',INVTP) INVTP_NAME, INVTP, SUBAMT, ACKAMT, CURRENCYTYPE, SUBQUTY, ACKQUTY, ACKNAV, COMMRO, FEE, AGENCYFEE, TRANSFERMFEE, OTHERFEE1, BALANCE, OSEATNO, OFUNDACCT, NETPOINT, OFUNDID, IBF_GET_PARAMNAME('SYSTEM','MELONMD',MELONMD) MELONMD_NAME, MELONMD, DIVIDENDRATE, FROZENCAUSE FROM V_T_ACKTRADEBLOTTER WHERE 1 = 1
AND FUNDACCT = #{sp.fundacct}
AND INVNM LIKE '%' || #{sp.invnm} || '%'
AND APKIND = #{sp.selApkindTwo}
AND REGIONCODE = #{sp.qway}
AND TANO = #{sp.tano}
AND NETPOINT = #{sp.netpoint}
ORDER BY INVNM,APDT,ACKNO ASC

	SELECT 
		 COUNT(*)
    FROM V_T_ACKTRADEBLOTTER
   WHERE 1 = 1

	  		 AND FUNDACCT = #{sp.fundacct}


	  		 AND INVNM LIKE '%' || #{sp.invnm} || '%'


	  		 AND APKIND = #{sp.selApkindTwo}


	  		 AND REGIONCODE = #{sp.qway}


	  		 AND TANO = #{sp.tano}


	  		 AND NETPOINT = #{sp.netpoint}

	    ORDER BY INVNM,APDT,ACKNO ASC

SELECT A.ACKDT, A.ACKNO, A.RETCODE, A.RETMSG, A.FUNDACCT, A.TRADEACCO, A.BANKNO, A.BANKACCO, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, A.FUNDID, IBF_GET_PARAMNAME('SYSTEM','APKIND',A.APKIND) APKIND_NAME, A.APKIND, A.CURRENCYTYPE, A.SUBQUTY, A.SUBAMT, A.ACKQUTY, A.FROZENBALANCE, A.ACKAMT, A.BALANCE, A.AVAILABLE, A.ACKNAV, IBF_GET_PARAMNAME('SYSTEM','MELONMD',A.MELONMD) MELONMD_NAME, A.MELONMD, A.DIVIDENDRATE, A.FROZENCAUSE, A.APPLYST, A.NETPOINT FROM S_ACKTRADEBLOTTER A, CUSTINFO C WHERE A.APKIND = '143' AND A.CUSTNO = C.CUSTNO
AND A.FUNDACCT = #{sp.fundacct}
AND C.INVNM LIKE '%' || #{sp.invnm} || '%'
AND A.REGIONCODE = #{sp.qway}
AND A.TANO = #{sp.tano}
AND A.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,A.ACKDT,A.ACKNO ASC

	SELECT 
		 COUNT(*)
    FROM S_ACKTRADEBLOTTER A,
         CUSTINFO C
   WHERE A.APKIND = '143'
     AND A.CUSTNO = C.CUSTNO

  		 AND A.FUNDACCT = #{sp.fundacct}


  		 AND C.INVNM LIKE '%' || #{sp.invnm} || '%'


  		 AND A.REGIONCODE = #{sp.qway}


  		 AND A.TANO = #{sp.tano}


  		 AND A.NETPOINT = #{sp.netpoint}

    ORDER BY C.INVNM,A.ACKDT,A.ACKNO ASC

	SELECT 
		 COUNT(*)
    FROM HS_ACKTRADEBLOTTER A,
         CUSTINFO C
    WHERE 1 = 1
   		AND A.APKIND = '143'
    	AND A.CUSTNO = C.CUSTNO

  		 AND A.ACKDT >=  #{sp.startDate}


  		 AND A.ACKDT <= #{sp.endDate}


  		 AND A.FUNDACCT = #{sp.fundacct}


  		 AND C.INVNM LIKE '%' || #{sp.invnm} || '%'


  		 AND A.REGIONCODE = #{sp.qway}


  		 AND A.TANO = #{sp.tano}

    ORDER BY C.INVNM,A.ACKDT,A.ACKNO ASC

SELECT A.ACKDT, A.ACKNO, A.RETCODE, A.RETMSG, A.FUNDACCT, A.TRADEACCO, A.BANKNO, A.BANKACCO, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, A.FUNDID, IBF_GET_PARAMNAME('SYSTEM','APKIND',A.APKIND) APKIND_NAME, A.APKIND, A.CURRENCYTYPE, A.SUBQUTY, A.SUBAMT, A.ACKQUTY, A.FROZENBALANCE, A.ACKAMT, A.BALANCE, A.AVAILABLE, A.ACKNAV, IBF_GET_PARAMNAME('SYSTEM','MELONMD',A.MELONMD) MELONMD_NAME, A.MELONMD, A.DIVIDENDRATE, A.FROZENCAUSE, A.APPLYST, A.NETPOINT FROM HS_ACKTRADEBLOTTER A, CUSTINFO C WHERE 1 = 1 AND A.APKIND = '143' AND A.CUSTNO = C.CUSTNO
AND A.ACKDT >= #{sp.startDate}
AND A.ACKDT <= #{sp.endDate}
AND A.FUNDACCT = #{sp.fundacct}
AND C.INVNM LIKE '%' || #{sp.invnm} || '%'
AND A.REGIONCODE = #{sp.qway}
AND A.TANO = #{sp.tano}
AND A.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,A.ACKDT,A.ACKNO ASC

SELECT COUNT(*) FROM ( SELECT APDT, SERIALNO, APPNO, FUNDACCT, TRADEACCO, BANKNO, NETPOINT, BANKACCO, APKIND, FUNDID, SUBQUTY, SUBAMT, COMMRO, OSEATNO, OFUNDACCT, OTRADEACCO, OFUNDID, MELONMD, DIVIDENDRATE, FROZENCAUSE, LARGEREDEEMFLAG, OLDAPPNO, PAYTYPE, PAYST, CAPITALNO, APPLYST, TRANSST, BROKER, BKIDTP, BKIDNO, CCHKFLAG, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, CUSTNO, REGIONCODE, TANO FROM H_APPTRADEBLOTTER UNION ALL SELECT APDT, SERIALNO, APPNO, FUNDACCT, TRADEACCO, BANKNO, NETPOINT, BANKACCO, APKIND, FUNDID, SUBQUTY, SUBAMT, COMMRO, OSEATNO, OFUNDACCT, OTRADEACCO, OFUNDID, MELONMD, DIVIDENDRATE, FROZENCAUSE, LARGEREDEEMFLAG, OLDAPPNO, PAYTYPE, PAYST, CAPITALNO, APPLYST, TRANSST, BROKER, BKIDTP, BKIDNO, CCHKFLAG, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, CUSTNO, REGIONCODE, TANO FROM L_APPTRADEBLOTTER ) A, FUNDINFO F, CUSTINFO C, (SELECT DISTINCT BROKEROFFICETEL,BROKERFAX,CUSTNO,BROKERIDNO FROM DS_CUSTINFOADD) DS WHERE 1 = 1 AND A.FUNDID = F.FUNDID AND A.CUSTNO = C.CUSTNO AND A.CUSTNO = DS.CUSTNO(+) AND A.BKIDNO = DS.BROKERIDNO(+)
AND A.APDT >= #{sp.startDate}
AND A.APDT <= #{sp.endDate}
AND A.FUNDACCT = #{sp.fundacct}
AND A.APKIND = #{sp.apkind}
AND C.INVNM LIKE '%' || #{sp.invnm} || '%'
AND A.REGIONCODE = #{sp.qway}
AND A.TANO = #{sp.tano}
AND F.FUNDID = #{sp.fundcode}
AND F.FUNDNM LIKE '%' || #{sp.fundnm} || '%'
AND A.NETPOINT = #{sp.netpoint}
ORDER BY APDT ASC

SELECT A.APDT, A.SERIALNO, A.APPNO, A.FUNDACCT, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, A.TRADEACCO, A.BANKNO, A.NETPOINT, A.BANKACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',A.APKIND) APKIND_NAME, A.APKIND, A.FUNDID, A.SUBQUTY, A.SUBAMT, F.CURRENCYTYPE, F.FUNDNM, A.COMMRO, A.OSEATNO, (SELECT SEATNM FROM SEAT WHERE SEATNO = A.OSEATNO) OSEATNM, A.OFUNDACCT, A.OTRADEACCO, (SELECT FUNDNM FROM FUNDINFO WHERE FUNDID = A.OFUNDID) OFUNDNAME, A.OFUNDID, IBF_GET_PARAMNAME('SYSTEM','MELONMD',A.MELONMD) MELONMD_NAME, A.MELONMD, A.DIVIDENDRATE, A.FROZENCAUSE, A.LARGEREDEEMFLAG, A.OLDAPPNO, A.PAYTYPE, A.PAYST, A.CAPITALNO, A.APPLYST, A.TRANSST, A.BROKER, A.BKIDTP, A.BKIDNO, A.CCHKFLAG, A.BOOKINGDT, A.VALIDAYS, A.SPECREDEEMFLAG, A.SPECREDEEMDT, A.DELAYDT, DS.BROKEROFFICETEL AS BROKERTEL, DS.BROKERFAX FROM ( SELECT APDT, SERIALNO, APPNO, FUNDACCT, TRADEACCO, BANKNO, NETPOINT, BANKACCO, APKIND, FUNDID, SUBQUTY, SUBAMT, COMMRO, OSEATNO, OFUNDACCT, OTRADEACCO, OFUNDID, MELONMD, DIVIDENDRATE, FROZENCAUSE, LARGEREDEEMFLAG, OLDAPPNO, PAYTYPE, PAYST, CAPITALNO, APPLYST, TRANSST, BROKER, BKIDTP, BKIDNO, CCHKFLAG, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, CUSTNO, REGIONCODE, TANO FROM H_APPTRADEBLOTTER UNION ALL SELECT APDT, SERIALNO, APPNO, FUNDACCT, TRADEACCO, BANKNO, NETPOINT, BANKACCO, APKIND, FUNDID, SUBQUTY, SUBAMT, COMMRO, OSEATNO, OFUNDACCT, OTRADEACCO, OFUNDID, MELONMD, DIVIDENDRATE, FROZENCAUSE, LARGEREDEEMFLAG, OLDAPPNO, PAYTYPE, PAYST, CAPITALNO, APPLYST, TRANSST, BROKER, BKIDTP, BKIDNO, CCHKFLAG, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, CUSTNO, REGIONCODE, TANO FROM L_APPTRADEBLOTTER )A, FUNDINFO F, CUSTINFO C, (SELECT DISTINCT BROKEROFFICETEL,BROKERFAX,CUSTNO,BROKERIDNO FROM DS_CUSTINFOADD) DS WHERE 1 = 1 AND A.FUNDID = F.FUNDID AND A.CUSTNO = C.CUSTNO AND A.CUSTNO = DS.CUSTNO(+) AND A.BKIDNO = DS.BROKERIDNO(+)
AND A.APDT >= #{sp.startDate}
AND A.APDT <= #{sp.endDate}
AND A.FUNDACCT = #{sp.fundacct}
AND A.APKIND = #{sp.selApkindOne}
AND C.INVNM LIKE '%' || #{sp.invnm} || '%'
AND A.REGIONCODE = #{sp.qway}
AND A.TANO = #{sp.tano}
AND F.FUNDID = #{sp.fundcode}
AND F.FUNDNM LIKE '%' || #{sp.fundnm} || '%'
AND A.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,A.APDT,A.APPNO ASC

SELECT A.APDT, A.SERIALNO, A.APPNO, A.FUNDACCT, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, A.TRADEACCO, A.BANKNO, A.NETPOINT, A.BANKACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',A.APKIND) APKIND_NAME, A.APKIND, A.FUNDID, F.FUNDNM, A.SUBQUTY, A.SUBAMT, F.CURRENCYTYPE, A.COMMRO, A.OSEATNO, (SELECT SEATNM FROM SEAT WHERE SEATNO = A.OSEATNO) OSEATNM, A.OFUNDACCT, A.OTRADEACCO, (SELECT FUNDNM FROM FUNDINFO WHERE FUNDID = A.OFUNDID) OFUNDNAME, A.OFUNDID, IBF_GET_PARAMNAME('SYSTEM','MELONMD',A.MELONMD) MELONMD_NAME, A.MELONMD, A.DIVIDENDRATE, A.FROZENCAUSE, A.LARGEREDEEMFLAG, A.OLDAPPNO, A.PAYTYPE, A.PAYST, A.CAPITALNO, A.APPLYST, A.TRANSST, A.BROKER, A.BKIDTP, A.BKIDNO, A.CCHKFLAG, A.BOOKINGDT, A.VALIDAYS, A.SPECREDEEMFLAG, A.SPECREDEEMDT, A.DELAYDT, DS.BROKEROFFICETEL AS BROKERTEL, DS.BROKERFAX FROM ( SELECT APDT, SERIALNO, APPNO, FUNDACCT, TRADEACCO, BANKNO, NETPOINT, BANKACCO, APKIND, FUNDID, SUBQUTY, SUBAMT, COMMRO, OSEATNO, OFUNDACCT, OTRADEACCO, OFUNDID, MELONMD, DIVIDENDRATE, FROZENCAUSE, LARGEREDEEMFLAG, OLDAPPNO, PAYTYPE, PAYST, CAPITALNO, APPLYST, TRANSST, BROKER, BKIDTP, BKIDNO, CCHKFLAG, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, CUSTNO, REGIONCODE, TANO FROM H_APPTRADEBLOTTER
UNION ALL
SELECT APDT, SERIALNO, APPNO, FUNDACCT, TRADEACCO, BANKNO, NETPOINT, BANKACCO, APKIND, FUNDID, SUBQUTY, SUBAMT, COMMRO, OSEATNO, OFUNDACCT, OTRADEACCO, OFUNDID, MELONMD, DIVIDENDRATE, FROZENCAUSE, LARGEREDEEMFLAG, OLDAPPNO, PAYTYPE, PAYST, CAPITALNO, APPLYST, TRANSST, BROKER, BKIDTP, BKIDNO, CCHKFLAG, BOOKINGDT, VALIDAYS, SPECREDEEMFLAG, SPECREDEEMDT, DELAYDT, CUSTNO, REGIONCODE, TANO FROM L_APPTRADEBLOTTER ) A, FUNDINFO F, CUSTINFO C, (SELECT DISTINCT BROKEROFFICETEL,BROKERFAX,CUSTNO,BROKERIDNO FROM DS_CUSTINFOADD) DS WHERE 1 = 1 AND A.FUNDID = F.FUNDID AND A.CUSTNO = C.CUSTNO AND A.CUSTNO = DS.CUSTNO(+) AND A.BKIDNO = DS.BROKERIDNO(+)
AND A.APDT >= #{sp.startDate}
AND A.APDT <= #{sp.endDate}
AND A.FUNDACCT = #{sp.fundacct}
AND A.APKIND = #{sp.selApkindOne}
AND C.INVNM LIKE '%' || #{sp.invnm} || '%'
AND A.REGIONCODE = #{sp.qway}
AND A.TANO = #{sp.tano}
AND F.FUNDID = #{sp.fundcode}
AND F.FUNDNM LIKE '%' || #{sp.fundnm} || '%'
AND A.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,A.APDT,A.APPNO ASC

		SELECT 
			COUNT(*)
   FROM HS_ACKTRADEBLOTTER A,
         CUSTINFO C
   WHERE 1 = 1
   	 AND A.CUSTNO = C.CUSTNO

  		 AND A.ACKDT >=  #{sp.startDate}


  		 AND A.ACKDT <= #{sp.endDate}


  		 AND A.FUNDACCT = #{sp.fundacct}


  		 AND A.APKIND = #{sp.selApkindTwo}


  		 AND C.INVNM LIKE '%' || #{sp.invnm} || '%'


  		 AND A.REGIONCODE = #{sp.qway}


  		 AND A.TANO = #{sp.tano}


  		 AND A.NETPOINT = #{sp.netpoint}

    ORDER BY C.INVNM,A.ACKDT,A.ACKNO ASC

SELECT A.ACKDT, A.ACKNO, A.RETCODE, A.RETMSG, A.APDT, A.SERIALNO, A.APPNO, A.FUNDACCT, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, A.TRADEACCO, A.BANKNO, A.BANKACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',A.APKIND) APKIND_NAME, A.APKIND, (SELECT FUNDNM FROM FUNDINFO WHERE FUNDID = A.FUNDID) FUNDNM, A.FUNDID, A.SUBQUTY, A.SUBAMT, A.CURRENCYTYPE, A.ACKQUTY, A.ACKAMT, A.BALANCE, A.COMMRO, A.SHARETYPE, A.FEE, A.INTEREST, A.ACKNAV, A.OSEATNO, (SELECT SEATNM FROM SEAT WHERE SEATNO = A.OSEATNO) OSEATNM, A.OFUNDACCT, A.OTRADEACCO, A.OFUNDID, A.OLDAPPNO, IBF_GET_PARAMNAME('SYSTEM','MELONMD',A.MELONMD) MELONMD_NAME, A.MELONMD, A.DIVIDENDRATE, A.FROZENCAUSE, A.APPLYST, A.NETPOINT, A.CLEARDT, (CASE WHEN A.REGIONCODE = '0001' THEN '网下' WHEN A.REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, A.REGIONCODE, C.IDTP, C.IDNO FROM HS_ACKTRADEBLOTTER A, CUSTINFO C WHERE 1 = 1 AND A.CUSTNO = C.CUSTNO
AND A.ACKDT >= #{sp.startDate}
AND A.ACKDT <= #{sp.endDate}
AND A.FUNDACCT = #{sp.fundacct}
AND A.APKIND = #{sp.selApkindTwo}
AND C.INVNM LIKE '%' || #{sp.invnm} || '%'
AND A.REGIONCODE = #{sp.qway}
AND A.TANO = #{sp.tano}
AND A.NETPOINT = #{sp.netpoint}
ORDER BY C.INVNM,A.ACKDT,A.ACKNO ASC

SELECT A.ACKDT, A.ACKNO, A.RETCODE, A.RETMSG, A.APDT, A.SERIALNO, A.APPNO, A.FUNDACCT, IBF_GET_PARAMNAME('SYSTEM','INVTP',C.INVTP) INVTP_NAME, C.INVTP, C.INVNM, A.TRADEACCO, A.BANKNO, A.BANKACCO, IBF_GET_PARAMNAME('SYSTEM','APKIND',A.APKIND) APKIND_NAME, A.APKIND, (SELECT FUNDNM FROM FUNDINFO WHERE FUNDID = A.FUNDID) FUNDNM, A.FUNDID, A.SUBQUTY, A.SUBAMT, A.CURRENCYTYPE, A.ACKQUTY, A.ACKAMT, A.BALANCE, A.COMMRO, A.SHARETYPE, A.FEE, A.INTEREST, A.ACKNAV, A.OSEATNO, (SELECT SEATNM FROM SEAT WHERE SEATNO = A.OSEATNO) OSEATNM, A.OFUNDACCT, A.OTRADEACCO, A.OFUNDID, A.OLDAPPNO, IBF_GET_PARAMNAME('SYSTEM','MELONMD',A.MELONMD) MELONMD_NAME, A.MELONMD, A.DIVIDENDRATE, A.FROZENCAUSE, A.APPLYST, A.NETPOINT, A.CLEARDT, (CASE WHEN A.REGIONCODE = '0001' THEN '网下' WHEN A.REGIONCODE = '9999' THEN '网上' END) REGIONCODE_NAME, A.REGIONCODE, C.IDTP, C.IDNO FROM HS_ACKTRADEBLOTTER A, CUSTINFO C WHERE 1 = 1 AND A.CUSTNO = C.CUSTNO
